import{_ as a,a0 as s,w as p,s as u,ao as n,I as e,x as r,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"學習數據結構與算法分析如何幫助您成為更優秀的開發人員 | LCTT x X-CMD","titleTemplate":false,"description":"學習數據結構與算法分析如何幫助您成為更優秀的開發人員 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習數據結構與算法分析如何幫助您成為更優秀的開發人員 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習數據結構與算法分析如何幫助您成為更優秀的開發人員 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20150823 How learning data structures and algorithms make you a better developer","title":"學習數據結構與算法分析如何幫助您成為更優秀的開發人員","tag":"201511","desc":""},"relativePath":"201511/20150823 How learning data structures and algorithms make you a better developer.md","filePath":"[post].md"}'),d={name:"201511/20150823 How learning data structures and algorithms make you a better developer.md"};function m(g,t,f,y,w,T){const o=s("Link");return p(),u("div",null,[t[34]||(t[34]=n('<h1 id="學習數據結構與算法分析如何幫助您成為更優秀的開發人員" tabindex="-1">學習數據結構與算法分析如何幫助您成為更優秀的開發人員 <a class="header-anchor" href="#學習數據結構與算法分析如何幫助您成為更優秀的開發人員" aria-label="Permalink to “學習數據結構與算法分析如何幫助您成為更優秀的開發人員”">​</a></h1><blockquote><p>&quot;相較於其它方式，我一直熱衷於推崇圍繞數據設計代碼，我想這也是Git能夠如此成功的一大原因[…]在我看來，區別程序員優劣的一大標準就在於他是否認為自己設計的代碼還是數據結構更為重要。&quot; -- Linus Torvalds</p></blockquote><hr><blockquote><p>&quot;優秀的數據結構與簡陋的代碼組合遠比反之的組合更好。&quot; -- Eric S. Raymond, The Cathedral and The Bazaar</p></blockquote><p>學習數據結構與算法分析會讓您成為一名出色的程序員。</p><p><strong>數據結構與算法分析是一種解決問題的思維模式。</strong> 在您的個人知識庫中，數據結構與算法分析的相關知識儲備越多，您將越多具備應對並解決各類繁雜問題的能力。掌握了這種思維模式，您還將有能力針對新問題提出更多以前想不到的漂亮的解決方案。</p><p>您將<em>更深入地</em>瞭解，計算機如何完成各項操作。無論您是否是直接使用給定的算法，它都影響着您作出的各種技術決定。從計算機操作系統的內存分配到RDBMS的內在工作機制，以及網絡協議如何實現將數據從地球的一個角落發送至另一個角落，這些大大小小的工作的完成，都離不開基礎的數據結構與算法，理解並掌握它將會讓您更瞭解計算機的運作機理。</p><p>對算法廣泛深入的學習能為您儲備解決方案來應對大體系的問題。之前建模困難時遇到的問題如今通常都能融合進經典的數據結構中得到很好地解決。即使是最基礎的數據結構，只要對它進行足夠深入的鑽研，您將會發現在每天的編程任務中都能經常用到這些知識。</p><p>有了這種思維模式，在遇到磨稜兩可的問題時，您將能夠想出新奇的解決方案。即使最初並沒有打算用數據結構與算法解決相應問題的情況，當真正用它們解決這些問題時您會發現它們將非常有用。要意識到這一點，您至少要對數據結構與算法分析的基礎知識有深入直觀的認識。</p><p>理論認識就講到這裏，讓我們一起看看下面幾個例子。</p><p>###最短路徑問題###</p><p>我們想要開發一個軟件來計算從一個國際機場出發到另一個國際機場的最短距離。假設我們受限於以下路線：</p><p><img src="http://www.happybearsoftware.com/assets/posts/how-learning-data-structures-and-algorithms-makes-you-a-better-developer/airport-graph-d2e32b3344b708383e405d67a80c29ea.svg" alt=""></p>',13)),e("p",null,[t[1]||(t[1]=r("從這張畫出機場各自之間的距離以及目的地的圖中，我們如何才能找到最短距離，比方説從赫爾辛基到倫敦？",-1)),e("strong",null,[l(o,{href:"http://en.wikipedia.org/wiki/Dijkstra's_algorithm"},{default:i(()=>[...t[0]||(t[0]=[r("Dijkstra算法",-1)])]),_:1})]),t[2]||(t[2]=r("是能讓我們在最短的時間得到正確答案的適用算法。",-1))]),t[35]||(t[35]=e("p",null,[r("在所有可能的解法中，如果您曾經遇到過這類問題，知道可以用Dijkstra算法求解，您大可不必從零開始實現它，只需"),e("em",null,[e("strong",null,"知道")]),r("該算法的代碼庫能幫助您解決相關的實現問題。")],-1)),e("p",null,[t[4]||(t[4]=r("如果你深入到該算法的實現中，您將深入理解一項著名的重要圖論算法。您會發現實際上該算法比較消耗資源，因此名為",-1)),l(o,{href:"http://en.wikipedia.org/wiki/A*_search_algorithm"},{default:i(()=>[...t[3]||(t[3]=[r("A*",-1)])]),_:1}),t[5]||(t[5]=r("的擴展經常用於代替該算法。這個算法應用廣泛，從機器人尋路的功能實現到TCP數據包路由，以及GPS尋徑問題都能應用到這個算法。",-1))]),t[36]||(t[36]=n(`<p>###先後排序問題###</p><p>您想要在開放式在線課程（MOOC，Massive Open Online Courses）平台上(如Udemy或Khan學院)學習某課程，有些課程之間彼此依賴。例如，用户學習牛頓力學（Newtonian Mechanics）課程前必須先修微積分（Calculus）課程，課程之間可以有多種依賴關係。用YAML表述舉例如下：</p><pre><code># Mapping from course name to requirements
#
# If you&#39;re a physcist or a mathematicisn and you&#39;re reading this, sincere
# apologies for the completely made-up dependency tree :)
courses:
  arithmetic:         []
  algebra:            [arithmetic]
  trigonometry:       [algebra]
  calculus:           [algebra, trigonometry]
  geometry:           [algebra]
  mechanics:          [calculus, trigonometry]
  atomic_physics:     [mechanics, calculus]
  electromagnetism:   [calculus, atomic_physics]
  radioactivity:      [algebra, atomic_physics]
  astrophysics:       [radioactivity, calculus]
  quantumn_mechanics: [atomic_physics, radioactivity, calculus]
</code></pre><p>鑑於以上這些依賴關係，作為一名用户，我希望系統能幫我列出必修課列表，讓我在之後可以選擇任意一門課程學習。如果我選擇了微積分（calculus）課程，我希望系統能返回以下列表：</p><pre><code>arithmetic -&gt; algebra -&gt; trigonometry -&gt; calculus
</code></pre><p>這裏有兩個潛在的重要約束條件：</p><ul><li>返回的必修課列表中，每門課都與下一門課存在依賴關係</li><li>我們不希望列表中有任何重複課程</li></ul><p>這是解決數據間依賴關係的例子，解決該問題的排序算法稱作拓撲排序算法(tsort，topological sort)。它適用於解決上述我們用YAML列出的依賴關係圖的情況，以下是在圖中顯示的相關結果(其中箭頭代表<code>需要先修的課程</code>):</p><p><img src="http://www.happybearsoftware.com/assets/posts/how-learning-data-structures-and-algorithms-makes-you-a-better-developer/course-graph-2f60f42bb0dc95319954ce34c02705a2.svg" alt=""></p><p>拓撲排序算法的實現就是從如上所示的圖中找到滿足各層次要求的依賴關係。因此如果我們只列出包含<code>radioactivity</code>和與它有依賴關係的子圖，運行tsort排序，會得到如下的順序表：</p><pre><code>arithmetic
algebra
trigonometry
calculus
mechanics
atomic_physics
radioactivity
</code></pre><p>這符合我們上面描述的需求，用户只需選出<code>radioactivity</code>，就能得到在此之前所有必修課程的有序列表。</p><p>在運用該排序算法之前，我們甚至不需要深入瞭解算法的實現細節。一般來説，你可能選擇的各種編程語言在其標準庫中都會有相應的算法實現。即使最壞的情況，Unix也會默認安裝<code>tsort</code>程序，運行<code>man tsort</code> 來了解該程序。</p><p>###其它拓撲排序適用場合###</p><ul><li><strong>類似<code>make</code>的工具</strong> 可以讓您聲明任務之間的依賴關係，這裏拓撲排序算法將從底層實現具有依賴關係的任務順序執行的功能。</li><li><strong>具有<code>require</code>指令的編程語言</strong>適用於要運行當前文件需先運行另一個文件的情況。這裏拓撲排序用於識別文件運行順序以保證每個文件只加載一次，且滿足所有文件間的依賴關係要求。</li><li><strong>帶有甘特圖的項目管理工具</strong>。甘特圖能直觀列出給定任務的所有依賴關係，在這些依賴關係之上能提供給用户任務完成的預估時間。我不常用到甘特圖，但這些繪製甘特圖的工具很可能會用到拓撲排序算法。</li></ul><p>###霍夫曼編碼實現數據壓縮###</p>`,16)),e("p",null,[l(o,{href:"http://en.wikipedia.org/wiki/Huffman_coding"},{default:i(()=>[...t[6]||(t[6]=[r("霍夫曼編碼",-1)])]),_:1}),t[7]||(t[7]=r("（Huffman coding）是一種用於無損數據壓縮的編碼算法。它的工作原理是先分析要壓縮的數據，再為每個字符創建一個二進制編碼。字符出現的越頻繁，編碼賦值越小。因此在一個數據集中",-1)),t[8]||(t[8]=e("code",null,"e",-1)),t[9]||(t[9]=r("可能會編碼為",-1)),t[10]||(t[10]=e("code",null,"111",-1)),t[11]||(t[11]=r("，而",-1)),t[12]||(t[12]=e("code",null,"x",-1)),t[13]||(t[13]=r("會編碼為",-1)),t[14]||(t[14]=e("code",null,"10010",-1)),t[15]||(t[15]=r("。創建了這種編碼模式，就可以串聯無定界符，也能正確地進行解碼。",-1))]),t[37]||(t[37]=e("p",null,[r("在gzip中使用的DEFLATE算法就結合了霍夫曼編碼與LZ77一同用於實現數據壓縮功能。gzip應用領域很廣，特別適用於文件壓縮(以"),e("code",null,".gz"),r("為擴展名的文件)以及用於數據傳輸中的http請求與應答。")],-1)),t[38]||(t[38]=e("p",null,"學會實現並使用霍夫曼編碼有如下益處：",-1)),e("ul",null,[t[19]||(t[19]=e("li",null,"您會理解為什麼較大的壓縮文件會獲得較好的整體壓縮效果(如壓縮的越多，壓縮率也越高)。這也是SPDY協議得以推崇的原因之一：在複雜的HTTP請求/響應過程數據有更好的壓縮效果。",-1)),t[20]||(t[20]=e("li",null,"您會了解數據傳輸過程中如果想要壓縮JavaScript/CSS文件，運行壓縮軟件是完全沒有意義的。PNG文件也是類似，因為它們已經使用DEFLATE算法完成了壓縮。",-1)),e("li",null,[t[17]||(t[17]=r("如果您試圖強行破譯加密的信息，您可能會發現由於重複數據壓縮質量更好，密文給定位的數據壓縮率將幫助您確定相關的",-1)),l(o,{href:"http://en.wikipedia.org/wiki/Block_cipher_mode_of_operation"},{default:i(()=>[...t[16]||(t[16]=[r("分組密碼工作模式",-1)])]),_:1}),t[18]||(t[18]=r("（block cipher mode of operation.）。",-1))])]),t[39]||(t[39]=e("p",null,"###下一步選擇學習什麼是困難的###",-1)),t[40]||(t[40]=e("p",null,"作為一名程序員應當做好持續學習的準備。為了成為一名web開發人員，您需要了解標記語言以及Ruby/Python、正則表達式、SQL、JavaScript等高級編程語言，還需要了解HTTP的工作原理，如何運行UNIX終端以及面向對象的編程藝術。您很難有效地預覽到未來的職業全景，因此選擇下一步要學習哪些知識是困難的。",-1)),t[41]||(t[41]=e("p",null,"我沒有快速學習的能力，因此我不得不在時間花費上非常謹慎。我希望儘可能地學習到有持久生命力的技能，即不會在幾年內就過時的技術。這意味着我也會猶豫這周是要學習JavaScript框架還是那些新的編程語言。",-1)),t[42]||(t[42]=e("p",null,"只要佔主導地位的計算模型體系不變，我們如今使用的數據結構與算法在未來也必定會以另外的形式繼續適用。您可以放心地將時間投入到深入掌握數據結構與算法知識中，它們將會成為您作為一名程序員的職業生涯中一筆長期巨大的財富。",-1)),t[43]||(t[43]=e("hr",null,null,-1)),e("p",null,[t[22]||(t[22]=r("via: ",-1)),l(o,{href:"http://www.happybearsoftware.com/how-learning-data-structures-and-algorithms-makes-you-a-better-developer"},{default:i(()=>[...t[21]||(t[21]=[r("http://www.happybearsoftware.com/how-learning-data-structures-and-algorithms-makes-you-a-better-developer",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=r("作者：",-1)),l(o,{href:"http://www.happybearsoftware.com/"},{default:i(()=>[...t[23]||(t[23]=[r("Happy Bear",-1)])]),_:1}),t[27]||(t[27]=r(" 譯者：",-1)),l(o,{href:"https://github.com/icybreaker"},{default:i(()=>[...t[24]||(t[24]=[r("icybreaker",-1)])]),_:1}),t[28]||(t[28]=r(" 校對：",-1)),l(o,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[25]||(t[25]=[r("Caroline",-1)])]),_:1})]),e("p",null,[t[31]||(t[31]=r("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[29]||(t[29]=[r("LCTT",-1)])]),_:1}),t[32]||(t[32]=r(" 原創翻譯，",-1)),l(o,{href:"https://linux.cn/"},{default:i(()=>[...t[30]||(t[30]=[r("Linux中國",-1)])]),_:1}),t[33]||(t[33]=r(" 榮譽推出",-1))])])}const C=a(d,[["render",m]]);export{v as __pageData,C as default};
